    const raw = String(req.headers.cookie || '');
    const parts = raw.split(';');
    for (const part of parts) {
      const chunk = part.trim();
      const i = chunk.indexOf('=');
      if (i <= 0) continue;
      const key = chunk.slice(0, i).trim();
      if (key !== target) continue;
